import React, { useCallback, useEffect, useState } from 'react';
import axios from 'axios';
import { getPropertyImage, money } from '../data';
import StayDialog from './StayDialog';
import './PropertyList.css';

const PropertyPhoto = ({ property, className = '' }) => {
  const [failed, setFailed] = useState(false);
  const imageUrl = getPropertyImage(property);

  if (!imageUrl || failed) return null;

  return (
    <div className={className === 'property-card-photo' ? 'property-photo-wrap' : 'property-dialog-photo-wrap'}>
      <img
        className={className}
        src={imageUrl}
        alt={`${property.pgName}${imageUrl.startsWith('/images/') ? ' representative room photo' : ' room'}`}
        loading="lazy"
        onError={() => setFailed(true)}
      />
      {imageUrl.startsWith('/images/') && <span className="property-photo-caption">Sample photo</span>}
    </div>
  );
};

const PropertyList = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedProperty, setSelectedProperty] = useState(null);

  const loadProperties = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.get('/api/properties/all');
      if (!Array.isArray(response.data)) {
        throw new Error('The properties API returned an invalid response.');
      }
      setProperties(response.data);
    } catch (requestError) {
      console.error('Error fetching properties:', requestError);
      setError('Could not load PG listings. Check that the backend and database are running, then try again.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadProperties();
  }, [loadProperties]);

  if (loading) {
    return <div className="property-state" role="status">Loading PG listings...</div>;
  }

  if (error) {
    return (
      <div className="property-state property-error" role="alert">
        <p>{error}</p>
        <button type="button" onClick={loadProperties}>Try again</button>
      </div>
    );
  }

  return (
    <section className="property-section" aria-labelledby="property-list-title">
      <h2 id="property-list-title">Available PGs &amp; Hostels</h2>
      {properties.length === 0 ? (
        <p className="property-empty">No listings are available right now.</p>
      ) : (
        <div className="property-grid">
          {properties.map((property) => (
            <article className="property-card" key={property.id}>
              <PropertyPhoto property={property} className="property-card-photo" />
              <div className="property-card-content">
                <h3>{property.pgName || 'PG / Hostel'}</h3>
                <p className="property-location">
                  {[property.locality, property.city].filter(Boolean).join(', ') || 'Location not listed'}
                </p>
                <p className="property-rent">
                  {property.rent != null ? `${money(property.rent)} / month` : 'Rent not listed'}
                </p>
                <button
                  className="property-details-button"
                  type="button"
                  onClick={() => setSelectedProperty(property)}
                  aria-label={`View details for ${property.pgName || 'this property'}`}
                >
                  View details
                </button>
              </div>
            </article>
          ))}
        </div>
      )}
      {selectedProperty && (
        <StayDialog property={selectedProperty} close={() => setSelectedProperty(null)} />
      )}
    </section>
  );
};

export default PropertyList;
